import 'package:flutter/material.dart';
class SpecialtyQuickAction { final String title; final IconData icon; final VoidCallback onTap; const SpecialtyQuickAction({required this.title,required this.icon,required this.onTap}); }
class QuickActionsGrid extends StatelessWidget { final Color accentColor; final List<SpecialtyQuickAction> actions; const QuickActionsGrid({super.key,required this.accentColor,required this.actions}); @override Widget build(BuildContext context){return GridView.builder(shrinkWrap:true,physics:const NeverScrollableScrollPhysics(),itemCount:actions.length,gridDelegate:const SliverGridDelegateWithFixedCrossAxisCount(crossAxisCount:3,crossAxisSpacing:10,mainAxisSpacing:10,childAspectRatio:1.05),itemBuilder:(_,i){final a=actions[i];return InkWell(onTap:a.onTap,borderRadius:BorderRadius.circular(14),child:Container(padding:const EdgeInsets.all(8),decoration:BoxDecoration(color:Theme.of(context).brightness==Brightness.dark?const Color(0xFF1A2540):Colors.white,borderRadius:BorderRadius.circular(14),border:Border.all(color:accentColor.withOpacity(.14))),child:Column(mainAxisAlignment:MainAxisAlignment.center,children:[Icon(a.icon,color:accentColor,size:26),const SizedBox(height:7),Text(a.title,textAlign:TextAlign.center,style:const TextStyle(fontSize:12,fontWeight:FontWeight.w700))])));});}}
